-- Co-op playtest fixes, step A+B (2026-09-27): new Balance Config fields shared.coop.choosingSkills (1 = Skills,
-- Shadow Clone and Companion keep attacking while their player chooses a level-up / chest; 0 = they wait) and
-- shared.coop.xpShareK (each player gets 1 / (1 + k × other players) of every EXP pickup). Only the `shared.coop`
-- object of the live config_schema is replaced so publish_config accepts them; their defaults (1 and 0) keep the
-- current behaviour until an admin publishes the co-op pass (2026-09-coop).
update public.config_schema set schema = jsonb_set(schema, '{properties,shared,properties,coop}',
  $j${"description":"Co-op","default":{},"type":"object","properties":{"bossHpPerMate":{"default":0.6,"description":"Boss / Guardian / Umbra HP + per extra player","type":"number","minimum":0,"maximum":1},"goldPerKill":{"default":0.1,"description":"Not used any more (guests pick up shared Gold drops); kept so older versions stay valid","type":"number","minimum":0,"maximum":1},"heartShare":{"default":60,"description":"Shared drops: a heart also heals allies this close to the player who took it","type":"number","minimum":0,"maximum":600},"pickTime":{"default":10,"description":"Level-up / chest: seconds to choose before a pick is made for you (the room keeps playing)","type":"number","minimum":0,"maximum":600},"shieldR":{"default":40,"description":"Shield bubble radius while choosing (monsters are pushed out)","type":"number","minimum":0,"maximum":400},"shieldPush":{"default":220,"description":"Shield bubble push speed","type":"number","minimum":0,"maximum":2200},"shieldAfter":{"default":5,"description":"Shield stays this long after choosing (s): time to get moving again, still no damage","type":"number","minimum":0,"maximum":600},"choosingSkills":{"default":1,"description":"Skills, Companion and Shadow Clone keep attacking while their player chooses a level-up / chest (1) or stop (0)","type":"number","minimum":0,"maximum":1},"xpShareK":{"default":0,"description":"EXP per pickup for each player = 1 / (1 + this × other players); 0 = everyone gets it all","type":"number","minimum":0,"maximum":2},"reviveTime":{"default":3,"description":"Seconds standing next to a downed ally to revive them","type":"number","minimum":0,"maximum":600},"reviveRange":{"default":22,"description":"Ally revive distance","type":"number","minimum":0,"maximum":220},"reviveHp":{"default":0.3,"description":"HP after an ally revive","type":"number","minimum":0,"maximum":1},"voteTime":{"default":15,"description":"Route vote time (s); the host breaks ties","type":"number","minimum":0,"maximum":600},"clearWait":{"default":30,"description":"Stage-end: wait for everyone to be ready at most (s)","type":"number","minimum":0,"maximum":600},"hostLost":{"default":5,"description":"Guests leave when no snapshot arrives for this long (s)","type":"number","minimum":0,"maximum":600}}}$j$::jsonb)
where id = 1;
